index 1b0d9aa..8f22c31 100644
--- a/src/server/routes/projects.ts
+++ b/src/server/routes/projects.ts
@@ -3,10 +3,17 @@ import { Router } from 'express';
 import { deleteProject } from '../projects/store.js';
+import { requireRole } from '../auth/roles.js';

 export const projectsRouter = Router();

 projectsRouter.delete('/projects/:id', async (req, res) => {
+  // Access enforcement: only an authenticated project admin may delete.
+  const session = req.session;
+  if (session === undefined || !requireRole(session, 'project-admin', req.params.id)) {
+    res.status(403).json({ error: 'forbidden' });
+    return;
+  }
   await deleteProject(req.params.id);
   res.status(204).end();
 });
